/** Reads visible SVG text, line ends and control symbols. Expected values were
 * transcribed from source physical39/40/42/44/46, not renderer helper exports. */
import assert from "node:assert/strict";
import {legacy2019Pm8SourceReview as source} from "./legacy-2019-pm8-source-review";
const decode=(s:string)=>s.replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&amp;/g,"&");
const attrs=(s:string)=>Object.fromEntries([...s.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],decode(m[2])]));
const tags=(html:string,name:string)=>[...html.matchAll(new RegExp(`<${name}\\b([^>]*)>`,"g"))].map(m=>attrs(m[1]));
const labels=(html:string):(Record<string,string>&{text:string})[]=>[...html.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>({...attrs(m[1]),text:decode(m[2])}));
const distance=(a:number[],b:number[])=>Math.hypot(a[0]-b[0],a[1]-b[1]);
const points=(s:string)=>s.split(/\s+/).map(p=>p.split(",").map(Number));
export function readLegacy2019Pm8Tree(html:string,path=false){
 const circles=tags(html,"circle");assert.equal(circles.length,7);circles.forEach(c=>assert.equal(c.r,"34"));const positions=circles.map(c=>[Number(c.cx),Number(c.cy)]),text=labels(html),node=(p:number[])=>{const i=positions.findIndex(c=>distance(p,c)<.001);assert(i>=0,"Edge must end at a visible circle centre");return i;},edges=tags(html,"line").map(l=>[node([Number(l.x1),Number(l.y1)]),node([Number(l.x2),Number(l.y2)])]);assert.equal(edges.length,6);assert.equal(new Set(edges.map(e=>e[1])).size,6);const root=positions.findIndex((_,i)=>!edges.some(e=>e[1]===i));assert(root>=0);const atLeaf=new Map<number,string>();for(const character of "ABCD"){const t=text.find(t=>t.text===`“${character}”`);assert(t);const candidates=positions.map((p,i)=>({i,d:distance(p,[Number(t.x),Number(t.y)])})).sort((a,b)=>a.d-b.d);assert(candidates[0].d<=65.001);atLeaf.set(candidates[0].i,character);}assert.equal(atLeaf.size,4);
 const codes:Record<string,string>={},weights:Record<string,number>={};function walk(i:number,code:string):number{const children=edges.filter(e=>e[0]===i).map(e=>e[1]).sort((a,b)=>positions[a][0]-positions[b][0]);assert.equal(children.length,atLeaf.has(i)?0:2);if(atLeaf.has(i))codes[atLeaf.get(i)!]=code;let weight=0;if(children.length)for(let side=0;side<2;side++){const child=children[side];assert(positions[child][1]>positions[i][1]);if(path){const expectedBits:Record<string,number[]>={"6,5":[390,65],"6,0":[630,95],"5,2":[210,220],"5,4":[415,215],"4,1":[380,350],"4,3":[545,350]},labelPosition=expectedBits[`${i},${child}`];assert(labelPosition);const bits=text.filter(t=>distance([Number(t.x),Number(t.y)],labelPosition)<.001);assert.equal(bits.length,1);assert.equal(bits[0].text,String(side));}weight+=walk(child,code+side);}else weight=source.example.counts["ABCD".indexOf(atLeaf.get(i)!)];if(!path){const value=text.filter(t=>distance([Number(t.x),Number(t.y)],positions[i])<.001);assert.equal(value.length,1);assert.equal(Number(value[0].text),weight);}return weight;}assert.equal(walk(root,""),19);assert.deepEqual(codes,{C:"00",B:"010",D:"011",A:"1"});if(path){assert.equal(text.filter(t=>/^\d+$/.test(t.text)).length,6,"Path circles must remain empty");const arrows=tags(html,"path").filter(p=>p["marker-end"]);assert.equal(arrows.length,3);const chain=[root,...["0","01","010"].map(code=>{let i=root;for(const bit of code)i=edges.filter(e=>e[0]===i).map(e=>e[1]).sort((a,b)=>positions[a][0]-positions[b][0])[Number(bit)];return i;})];arrows.forEach((p,n)=>{const m=p.d.match(/^M ([\d.]+) ([\d.]+) Q [\d.]+ [\d.]+ ([\d.]+) ([\d.]+)$/);assert(m);assert(distance(m.slice(1,3).map(Number),positions[chain[n]])<60);assert(distance(m.slice(3,5).map(Number),positions[chain[n+1]])<60);});}return codes;
}
export function readLegacy2019Pm8Arrays(html:string){
 const ts=labels(html),headers=ts.filter(t=>/^\d$/.test(t.text)&&Number(t.y)<115).sort((a,b)=>Number(a.x)-Number(b.x));assert.deepEqual(headers.map(t=>t.text),["0","1","2","3","4","5","6"]);const xs=headers.map(t=>Number(t.x)),result:Record<string,number[]>={};for(const name of["parent","left","right","freq"]as const){const label=ts.find(t=>t.text===name);assert(label);const row=ts.filter(t=>t.y===label.y&&Number(t.x)>Number(label.x)).sort((a,b)=>Number(a.x)-Number(b.x));assert.deepEqual(row.map(t=>Number(t.x)),xs);const values=row.map(t=>Number(t.text.replace("−","-")));assert.deepEqual(values,source.example[name]);result[name]=values;}assert(ts.some(t=>t.text==="配列名")&&ts.some(t=>t.text==="要素番号"));const arrows=tags(html,"polyline");assert.equal(arrows.length,6);const seen=new Set<number>();for(const arrow of arrows){assert(arrow["marker-end"]);const ps=points(arrow.points);assert.equal(ps.length,4);assert.equal(ps[0][1],315);assert.equal(ps[3][1],315);assert(ps[1][1]>315&&ps[1][1]===ps[2][1]);assert.equal(ps[0][0],ps[1][0]);assert.equal(ps[2][0],ps[3][0]);const child=xs.indexOf(ps[0][0]);assert(child>=0&&child<6&&!seen.has(child));seen.add(child);const parent=xs.map((x,i)=>({i,d:Math.abs(x-ps[3][0])})).sort((a,b)=>a.d-b.d)[0];assert(parent.d<=8);assert.equal(parent.i,source.example.parent[child],"Arrow must point from child column to parent column");}return result;
}
const p1=[
 "○副プログラム: Huffman(整数型: size, 整数型: parent[], 整数型: left[], 整数型: right[], 整数型: freq[])","○整数型: i, j, nsize","○整数型: node[]","SortNode(size, parent, freq, nsize, node)","c","i ← node[0] /* 最も小さい値をもつ要素組の要素番号 */","j ← node[1] /* 2番目に小さい値をもつ要素組の要素番号 */","left[size] ← i","right[size] ← j","freq[size] ← freq[i] ＋ freq[j] /* 子の値の合計 */","parent[i] ← size /* 子に親の要素番号を格納 */","parent[j] ← size /* 子に親の要素番号を格納 */","size ← size ＋ 1","SortNode(size, parent, freq, nsize, node)","","○副プログラム: SortNode(整数型: size, 整数型: parent[], 整数型: freq[], 整数型: nsize, 整数型: node[])","○整数型: i","nsize ← 0","i: 0, i < size, 1","d","node[nsize] ← i","nsize ← nsize ＋ 1","","","Sort(freq, nsize, node)",
];
const p2=["○副プログラム: Encode(整数型: k, 整数型: parent[], 整数型: left[])","e","Encode(parent[k], parent, left)","f",'print("0") /* 0を表示する */','print("1") /* 1を表示する */',"",""];
export function assertLegacy2019Pm8ProgramDescription(text:string,which:1|2){
 const expected=which===1?p1:p2,norm=(s:string)=>s.replace(/\s+/g," ");expected.forEach((line,i)=>{if(!line)return;const label=/^[cdef]$/.test(line)?`[ ${line} ]`:line;assert(norm(text).includes(norm(`${i+1}: ${label}`)),`Missing accessible program line${i+1}`);});
 for(const premise of which===1?["行5〜15","前判定条件","行19〜24","i<size","行20〜23","単岐選択","行25のSortは繰返しの外"]:["行2〜8","単岐選択","先に行3の再帰呼出し","行4〜7","真なら行5","偽なら行6","双岐選択"])assert(text.includes(premise),"Missing accessible control: "+premise);
}
export function readLegacy2019Pm8Program(html:string,which:1|2){
 const ts=labels(html),expected=which===1?p1:p2,nums=ts.filter(t=>t.x==="70").sort((a,b)=>Number(a.y)-Number(b.y));assert.deepEqual(nums.map(t=>Number(t.text)),expected.map((_,i)=>i+1));const ys=nums.map(t=>Number(t.y)),norm=(s:string)=>s.replace(/\s+/g," ").trim(),rows=ys.map((y,i)=>{const next=ys[i+1]??y+45;return norm(ts.filter(t=>Number(t.x)>100&&Number(t.y)>=y&&Number(t.y)<next).sort((a,b)=>Number(a.y)-Number(b.y)||Number(a.x)-Number(b.x)).map(t=>t.text).join(" "));});assert.deepEqual(rows,expected.map(norm));const squares=tags(html,"rect").filter(r=>r.width==="12"&&r.height==="12"),triangles=tags(html,"polygon"),lines=tags(html,"line");triangles.forEach(t=>assert.equal(t.style,"fill:currentColor","Source branch markers are filled triangles"));
 const control=(a:number,b:number,x:number,kind:"loop"|"branch")=>{const top=ys[a-1]-14,bottom=ys[b-1]+(kind==="loop"?12:7);assert(lines.some(l=>Number(l.x1)===x&&Number(l.x2)===x&&Number(l.y1)===top&&Number(l.y2)===bottom),"Missing/moved control span");if(kind==="loop")for(const y of[top,bottom])assert(squares.some(r=>Number(r.x)+6===x&&Number(r.y)+6===y));else{assert(triangles.some(t=>t.points===`${x},${top-7} ${x-7},${top+7} ${x+7},${top+7}`));const y=ys[b-1];assert(triangles.some(t=>t.points===`${x-7},${y-7} ${x+7},${y-7} ${x},${y+7}`));}};
 if(which===1){assert.equal(squares.length,4);assert.equal(triangles.length,2);control(5,15,140,"loop");control(19,24,140,"loop");control(20,23,185,"branch");assert(Number(ts.find(t=>t.text==="Sort(freq, nsize, node)")!.x)<185,"Final Sort remains outside nested controls");}else{assert.equal(squares.length,0);assert.equal(triangles.length,4);control(2,8,140,"branch");control(4,7,185,"branch");assert(lines.some(l=>l.x1==="185"&&l.x2==="210"&&Number(l.y1)===ys[5]-22&&l.y1===l.y2),"False branch separator between print0 and print1");}const blanks=tags(html,"rect").filter(r=>r.width==="125"&&r.height==="34");assert.equal(blanks.length,2);for(const value of which===1?["c","d"]:["e","f"]){const t=ts.find(t=>t.text===value);assert(t);assert(blanks.some(r=>Number(r.x)<Number(t.x)&&Number(r.x)+125>Number(t.x)&&Number(r.y)<Number(t.y)&&Number(r.y)+34>Number(t.y)));}return rows;
}
export function readLegacy2019Pm8Ratio(html:string){const ts=labels(html),top=ts.find(t=>t.text==="ハフマン符号化によって圧縮したときの総ビット長"),bottom=ts.find(t=>t.text==="2ビットの固定長で表現したときの総ビット長");assert(top&&bottom);assert(tags(html,"line").some(l=>l.y1===l.y2&&Number(top.y)<Number(l.y1)&&Number(l.y1)<Number(bottom.y)&&Number(l.x1)<Number(top.x)&&Number(l.x2)>Number(top.x)));assert(ts.some(t=>t.text==="圧縮率 ＝"));}
